     1→import * as vscode from 'vscode';
     2→import { TabInfo, ContextSnapshot, TurnSnapshot, SessionSummary } from './types';
     3→import { TabRelevanceScorer } from './tabRelevanceScorer';
     4→import { TokenBudgetEstimator } from './tokenBudgetEstimator';
     5→import { TokenizerService } from './tokenizerService';
     6→import { ModelProfile, MODEL_PROFILES, DEFAULT_MODEL_ID, getModel } from './modelProfiles';
     7→
     8→const PINNED_FILES_KEY = 'tokalator.pinnedFiles';
     9→const SELECTED_MODEL_KEY = 'tokalator.selectedModel';
    10→const SESSION_KEY = 'tokalator.lastSession';
    11→
    12→/**
    13→ * Core engine that tracks all editor state and produces real-time ContextSnapshots.
    14→ *
    15→ * Subscribes to:
    16→ *  - Active editor changes
    17→ *  - Tab open/close events
    18→ *  - Text document changes
    19→ *  - Diagnostics changes
    20→ *
    21→ * Emits:
    22→ *  - onDidUpdateSnapshot: fires with a fresh ContextSnapshot after each state change
    23→ */
    24→export class ContextMonitor implements vscode.Disposable {
    25→
    26→  private readonly _onDidUpdateSnapshot = new vscode.EventEmitter<ContextSnapshot>();
    27→  readonly onDidUpdateSnapshot = this._onDidUpdateSnapshot.event;
    28→
    29→  private readonly scorer = new TabRelevanceScorer();
    30→  private readonly tokenizer = new TokenizerService();
    31→  private readonly estimator = new TokenBudgetEstimator(this.tokenizer);
    32→
    33→  private pinnedFiles = new Set<string>();
    34→  private chatTurnCount = 0;
    35→  private turnHistory: TurnSnapshot[] = [];
    36→  private lastEditTimestamps = new Map<string, number>();
    37→  private disposables: vscode.Disposable[] = [];
    38→  private refreshTimer: ReturnType<typeof setInterval> | undefined;
    39→
    40→  private latestSnapshot: ContextSnapshot | null = null;
    41→  private debounceTimer: ReturnType<typeof setTimeout> | undefined;
    42→  private isRefreshing = false;
    43→
    44→  private activeModel: ModelProfile;
    45→  private workspaceFileTokens = 0;
    46→  private workspaceFileCount = 0;
    47→
    48→  // Session tracking
    49→  private peakTokens = 0;
    50→  private peakPercent = 0;
    51→  private fileEditCounts = new Map<string, number>();
    52→
    53→  constructor(private readonly workspaceState?: vscode.Memento) {
    54→    // Load persisted pinned files (normalize URIs for consistent matching)
    55→    if (workspaceState) {
    56→      const saved = workspaceState.get<string[]>(PINNED_FILES_KEY, []);
    57→      this.pinnedFiles = new Set(saved.map(u => this.normalizeUri(u)));
    58→    }
    59→
    60→    // Load persisted model selection
    61→    const savedModelId = workspaceState?.get<string>(SELECTED_MODEL_KEY, DEFAULT_MODEL_ID) || DEFAULT_MODEL_ID;
    62→    this.activeModel = getModel(savedModelId);
    63→    this.estimator.setProvider(this.activeModel.provider);
    64→
    65→    // Scan workspace files on startup
    66→    this.scanWorkspaceFiles();
    67→
    68→    // Debounced refresh to avoid perf issues from rapid event firing
    69→    const debouncedRefresh = () => {
    70→      if (this.debounceTimer) { clearTimeout(this.debounceTimer); }
    71→      this.debounceTimer = setTimeout(() => this.refresh(), 300);
    72→    };
    73→
    74→    // Subscribe to VS Code events
    75→    this.disposables.push(
    76→      vscode.window.onDidChangeActiveTextEditor(() => debouncedRefresh()),
    77→      vscode.window.onDidChangeTextEditorSelection(() => debouncedRefresh()),
    78→      vscode.window.tabGroups.onDidChangeTabs(() => debouncedRefresh()),
    79→      vscode.workspace.onDidChangeTextDocument(e => {
    80→        const uri = e.document.uri.toString();
    81→        this.lastEditTimestamps.set(uri, Date.now());
    82→        this.fileEditCounts.set(uri, (this.fileEditCounts.get(uri) || 0) + 1);
    83→        debouncedRefresh();
    84→      }),
    85→      vscode.workspace.onDidOpenTextDocument(() => debouncedRefresh()),
    86→      // Clean up caches when documents close (memory leak fix)
    87→      vscode.workspace.onDidCloseTextDocument(doc => {
    88→        const uri = doc.uri.toString();
    89→        this.lastEditTimestamps.delete(uri);
    90→        this.estimator.clearCacheFor(uri);
    91→        debouncedRefresh();
    92→      }),
    93→      vscode.languages.onDidChangeDiagnostics(() => debouncedRefresh()),
    94→      // Sync model when settings change (skip if already on that model to avoid loop)
    95→      vscode.workspace.onDidChangeConfiguration(e => {
    96→        if (e.affectsConfiguration('tokalator.model')) {
    97→          const cfg = vscode.workspace.getConfiguration('tokalator');
    98→          const modelId = cfg.get<string>('model', DEFAULT_MODEL_ID);
    99→          if (modelId !== this.activeModel.id) {
   100→            this.setModel(modelId);
   101→          }
   102→        }
   103→      }),
   104→    );
   105→
   106→    // Periodic refresh for time-based scoring (recency decay)
   107→    const config = vscode.workspace.getConfiguration('tokalator');
   108→    const interval = config.get<number>('autoRefreshInterval', 2000);
   109→    this.refreshTimer = setInterval(() => this.refresh(), interval);
   110→
   111→    // Initial snapshot
   112→    this.refresh();
   113→  }
   114→
   115→  /**
   116→   * Build a fresh snapshot and emit it.
   117→   */
   118→  async refresh(): Promise<void> {
   119→    if (this.isRefreshing) { return; }
   120→    this.isRefreshing = true;
   121→    try {
   122→      const snapshot = await this.buildSnapshot();
   123→      this.latestSnapshot = snapshot;
   124→      this._onDidUpdateSnapshot.fire(snapshot);
   125→    } finally {
   126→      this.isRefreshing = false;
   127→    }
   128→  }
   129→
   130→  /**
   131→   * Get the most recent snapshot without triggering a refresh.
   132→   */
   133→  getLatestSnapshot(): ContextSnapshot | null {
   134→    return this.latestSnapshot;
   135→  }
   136→
   137→  /**
   138→   * Normalize a URI string for consistent Set matching.
   139→   */
   140→  private normalizeUri(uri: string): string {
   141→    try {
   142→      return vscode.Uri.parse(uri).toString();
   143→    } catch {
   144→      return uri;
   145→    }
   146→  }
   147→
   148→  /**
   149→   * Pin a file URI so it's always scored as maximum relevance.
   150→   */
   151→  pinFile(uri: string): void {
   152→    this.pinnedFiles.add(this.normalizeUri(uri));
   153→    this.persistPins();
   154→    this.refresh();
   155→  }
   156→
   157→  /**
   158→   * Unpin a file.
   159→   */
   160→  unpinFile(uri: string): void {
   161→    this.pinnedFiles.delete(this.normalizeUri(uri));
   162→    this.persistPins();
   163→    this.refresh();
   164→  }
   165→
   166→  /**
   167→   * Clear all pins.
   168→   */
   169→  clearPins(): void {
   170→    this.pinnedFiles.clear();
   171→    this.persistPins();
   172→    this.refresh();
   173→  }
   174→
   175→  /**
   176→   * Persist pinned files to workspace state.
   177→   */
   178→  private persistPins(): void {
   179→    if (this.workspaceState) {
   180→      this.workspaceState.update(PINNED_FILES_KEY, Array.from(this.pinnedFiles));
   181→    }
   182→  }
   183→
   184→  /**
   185→   * Increment the conversation turn counter and capture a turn snapshot.
   186→   * Only call this for actual user interactions, not status checks.
   187→   */
   188→  async incrementChatTurns(): Promise<void> {
   189→    this.chatTurnCount++;
   190→
   191→    // Capture a turn snapshot for compaction tracking
   192→    const snapshot = this.latestSnapshot;
   193→    if (snapshot) {
   194→      const fileTokens = snapshot.tabs.reduce((s, t) => s + t.estimatedTokens, 0);
   195→      const overheadTokens = snapshot.totalEstimatedTokens - fileTokens;
   196→      this.turnHistory.push({
   197→        turn: this.chatTurnCount,
   198→        timestamp: Date.now(),
   199→        inputTokens: snapshot.totalEstimatedTokens,
   200→        outputReserved: this.activeModel.maxOutput,
   201→        fileTokens,
   202→        overheadTokens,
   203→        tabCount: snapshot.tabs.length,
   204→        pinnedCount: this.pinnedFiles.size,
   205→      });
   206→    }
   207→
   208→    this.refresh();
   209→  }
   210→
   211→  /**
   212→   * Estimate the token cost of the *next* chat turn before sending.
   213→   * This gives users a preview of what will be consumed.
   214→   */
   215→  async previewNextTurn(): Promise<{
   216→    currentInput: number;
   217→    nextTurnEstimate: number;
   218→    conversationGrowth: number;
   219→    outputReserved: number;
   220→    remainingCapacity: number;
   221→    percentAfterTurn: number;
   222→    windowCapacity: number;
   223→    warning: string | null;
   224→  }> {
   225→    await this.refresh();
   226→    const snapshot = this.latestSnapshot;
   227→    if (!snapshot) {
   228→      return {
   229→        currentInput: 0, nextTurnEstimate: 0, conversationGrowth: 800,
   230→        outputReserved: this.activeModel.maxOutput, remainingCapacity: this.activeModel.contextWindow,
   231→        percentAfterTurn: 0, windowCapacity: this.activeModel.contextWindow, warning: null,
   232→      };
   233→    }
   234→
   235→    // Each turn adds ~800 tokens (user message + assistant response)
   236→    const perTurnCost = 800;
   237→    const nextTurnInput = snapshot.totalEstimatedTokens + perTurnCost;
   238→    const nextPercent = Math.min((nextTurnInput / snapshot.windowCapacity) * 100, 100);
   239→    const remaining = Math.max(snapshot.windowCapacity - nextTurnInput - this.activeModel.maxOutput, 0);
   240→
   241→    let warning: string | null = null;
   242→    if (nextPercent >= 90) {
   243→      warning = 'Next turn will push you past 90% — high risk of context overflow';
   244→    } else if (nextPercent >= 75) {
   245→      warning = 'Approaching context limit — consider closing tabs or resetting';
   246→    }
   247→
   248→    // Check if next turn crosses the rot threshold
   249→    if (this.chatTurnCount + 1 >= this.activeModel.rotThreshold) {
   250→      const rotMsg = `Turn ${this.chatTurnCount + 1} will cross context rot threshold (${this.activeModel.rotThreshold})`;
   251→      warning = warning ? `${warning}. ${rotMsg}` : rotMsg;
   252→    }
   253→
   254→    return {
   255→      currentInput: snapshot.totalEstimatedTokens,
   256→      nextTurnEstimate: nextTurnInput,
   257→      conversationGrowth: perTurnCost,
   258→      outputReserved: this.activeModel.maxOutput,
   259→      remainingCapacity: remaining,
   260→      percentAfterTurn: nextPercent,
   261→      windowCapacity: snapshot.windowCapacity,
   262→      warning,
   263→    };
   264→  }
   265→
   266→  /**
   267→   * Reset conversation turn counter and clear turn history.
   268→   */
   269→  resetChatTurns(): void {
   270→    this.chatTurnCount = 0;
   271→    this.turnHistory = [];
   272→    this.refresh();
   273→  }
   274→
   275→  /**
   276→   * Get current chat turn count.
   277→   */
   278→  getChatTurnCount(): number {
   279→    return this.chatTurnCount;
   280→  }
   281→
   282→  /**
   283→   * Get the per-turn snapshot history for compaction analysis.
   284→   */
   285→  getTurnHistory(): TurnSnapshot[] {
   286→    return [...this.turnHistory];
   287→  }
   288→
   289→  /**
   290→   * Close tabs below relevance threshold.
   291→   * Returns the list of closed tab labels.
   292→   */
   293→  async optimizeTabs(): Promise<string[]> {
   294→    const config = vscode.workspace.getConfiguration('tokalator');
   295→    const threshold = config.get<number>('relevanceThreshold', 0.3);
   296→
   297→    const snapshot = await this.buildSnapshot();
   298→    const toClose = snapshot.tabs.filter(
   299→      t => t.relevanceScore < threshold && !t.isActive && !t.isPinned
   300→    );
   301→
   302→    const closed: string[] = [];
   303→    for (const tab of toClose) {
   304→      const allTabs = vscode.window.tabGroups.all.flatMap(g => g.tabs);
   305→      const vsTab = allTabs.find(t => {
   306→        if (t.input instanceof vscode.TabInputText) {
   307→          return t.input.uri.toString() === tab.uri.toString();
   308→        }
   309→        return false;
   310→      });
   311→      if (vsTab) {
   312→        await vscode.window.tabGroups.close(vsTab);
   313→        closed.push(tab.label);
   314→      }
   315→    }
   316→
   317→    return closed;
   318→  }
   319→
   320→  /**
   321→   * Build the full context snapshot.
   322→   */
   323→  private async buildSnapshot(): Promise<ContextSnapshot> {
   324→    const config = vscode.workspace.getConfiguration('tokalator');
   325→    const windowCapacity = this.activeModel.contextWindow;
   326→    const rotWarning = this.activeModel.rotThreshold;
   327→
   328→    // 1. Gather all open tabs
   329→    let tabs = this.gatherTabs();
   330→
   331→    // 2. Estimate tokens for each tab
   332→    tabs = await this.estimator.estimateAllTabs(tabs);
   333→
   334→    // 3. Score relevance
   335→    tabs = this.scorer.scoreAll(tabs, vscode.window.activeTextEditor);
   336→
   337→    // 4. Sort by relevance (highest first)
   338→    tabs.sort((a, b) => b.relevanceScore - a.relevanceScore);
   339→
   340→    // 5. Gather diagnostics summary
   341→    const diagnosticsSummary = this.gatherDiagnosticsSummary();
   342→
   343→    // 6. Count instruction files in workspace
   344→    const instructionFiles = await this.countInstructionFiles();
   345→
   346→    // 7. Compute budget
   347→    const budget = this.estimator.computeBudget(
   348→      tabs,
   349→      this.chatTurnCount,
   350→      instructionFiles,
   351→      windowCapacity
   352→    );
   353→
   354→    // Track peak usage for session summary
   355→    if (budget.used > this.peakTokens) {
   356→      this.peakTokens = budget.used;
   357→      this.peakPercent = budget.percent;
   358→    }
   359→
   360→    // 8. Determine budget level (simplified from percentage)
   361→    let budgetLevel: 'low' | 'medium' | 'high';
   362→    if (budget.percent > 85) {
   363→      budgetLevel = 'high';
   364→    } else if (budget.percent > 60) {
   365→      budgetLevel = 'medium';
   366→    } else {
   367→      budgetLevel = 'low';
   368→    }
   369→
   370→    // 9. Determine health and reasons
   371→    const healthReasons: string[] = [];
   372→    let contextHealth: ContextSnapshot['contextHealth'] = 'healthy';
   373→
   374→    if (budgetLevel === 'high') {
   375→      contextHealth = 'critical';
   376→      healthReasons.push('Token budget is high — context overflow risk');
   377→    } else if (budgetLevel === 'medium') {
   378→      contextHealth = 'warning';
   379→      healthReasons.push('Token budget is medium — consider closing unused tabs');
   380→    }
   381→
   382→    if (this.chatTurnCount >= rotWarning) {
   383→      contextHealth = contextHealth === 'critical' ? 'critical' : 'warning';
   384→      healthReasons.push(`${this.chatTurnCount} chat turns — context may be stale`);
   385→    }
   386→
   387→    const distractors = tabs.filter(t => {
   388→      const threshold = config.get<number>('relevanceThreshold', 0.3);
   389→      return t.relevanceScore < threshold && !t.isActive && !t.isPinned;
   390→    });
   391→    if (distractors.length > 3) {
   392→      contextHealth = contextHealth === 'critical' ? 'critical' : 'warning';
   393→      healthReasons.push(`${distractors.length} low-relevance tabs open`);
   394→    }
   395→
   396→    if (healthReasons.length === 0) {
   397→      healthReasons.push('Token budget looks good');
   398→    }
   399→
   400→    const activeFile = tabs.find(t => t.isActive) || null;
   401→
   402→    return {
   403→      timestamp: Date.now(),
   404→      activeFile,
   405→      tabs,
   406→      pinnedFiles: this.pinnedFiles,
   407→      totalEstimatedTokens: budget.used,
   408→      windowCapacity,
   409→      usagePercent: budget.percent,
   410→      budgetLevel,
   411→      diagnosticsSummary,
   412→      chatTurnCount: this.chatTurnCount,
   413→      contextHealth,
   414→      healthReasons,
   415→      modelId: this.activeModel.id,
   416→      modelLabel: this.activeModel.label,
   417→      workspaceFileCount: this.workspaceFileCount,
   418→      workspaceFileTokens: this.workspaceFileTokens,
   419→      tokenizerType: this.tokenizer.getTokenizerType(this.activeModel.provider),
   420→      tokenizerLabel: this.tokenizer.getTokenizerLabel(this.activeModel.provider),
   421→      turnHistory: [...this.turnHistory],
   422→      budgetBreakdown: budget.breakdown,
   423→    };
   424→  }
   425→
   426→  /**
   427→   * Gather TabInfo from all open tab groups.
   428→   */
   429→  private gatherTabs(): TabInfo[] {
   430→    const tabs: TabInfo[] = [];
   431→    const workspaceRoot = vscode.workspace.workspaceFolders?.[0]?.uri.fsPath || '';
   432→
   433→    for (const group of vscode.window.tabGroups.all) {
   434→      for (const tab of group.tabs) {
   435→        if (!(tab.input instanceof vscode.TabInputText)) { continue; }
   436→
   437→        const uri = tab.input.uri;
   438→        const fsPath = uri.fsPath;
   439→        const relativePath = workspaceRoot
   440→          ? fsPath.replace(workspaceRoot, '').replace(/^\//, '')
   441→          : fsPath;
   442→
   443→        // Get language ID from open documents
   444→        const openDoc = vscode.workspace.textDocuments.find(
   445→          d => d.uri.toString() === uri.toString()
   446→        );
   447→        const languageId = openDoc?.languageId || this.guessLanguage(fsPath);
   448→
   449→        // Get diagnostics for this file
   450→        const diagnostics = vscode.languages.getDiagnostics(uri);
   451→        const diagnosticCount = diagnostics.length;
   452→
   453→        // Get last edit timestamp
   454→        const lastEdit = this.lastEditTimestamps.get(uri.toString()) || 0;
   455→
   456→        tabs.push({
   457→          uri,
   458→          label: tab.label,
   459→          languageId,
   460→          relativePath,
   461→          estimatedTokens: 0,   // filled later by estimator
   462→          relevanceScore: 0,     // filled later by scorer
   463→          relevanceReason: '',
   464→          isActive: tab.isActive,
   465→          isDirty: tab.isDirty,
   466→          isPinned: this.pinnedFiles.has(uri.toString()),
   467→          diagnosticCount,
   468→          lastEditTimestamp: lastEdit,
   469→        });
   470→      }
   471→    }
   472→
   473→    return tabs;
   474→  }
   475→
   476→  /**
   477→   * Aggregate diagnostics across all open files.
   478→   */
   479→  private gatherDiagnosticsSummary(): { errors: number; warnings: number; info: number } {
   480→    const allDiags = vscode.languages.getDiagnostics();
   481→    let errors = 0, warnings = 0, info = 0;
   482→
   483→    for (const [, diags] of allDiags) {
   484→      for (const d of diags) {
   485→        switch (d.severity) {
   486→          case vscode.DiagnosticSeverity.Error: errors++; break;
   487→          case vscode.DiagnosticSeverity.Warning: warnings++; break;
   488→          default: info++; break;
   489→        }
   490→      }
   491→    }
   492→
   493→    return { errors, warnings, info };
   494→  }
   495→
   496→  /**
   497→   * Count .instructions.md files in the workspace (they consume context budget).
   498→   */
   499→  private async countInstructionFiles(): Promise<number> {
   500→    try {
   501→      const files = await vscode.workspace.findFiles('**/*.instructions.md', '**/node_modules/**', 20);
   502→      // Also count .github/copilot-instructions.md
   503→      const copilotInstr = await vscode.workspace.findFiles('.github/copilot-instructions.md', undefined, 1);
   504→      return files.length + copilotInstr.length;
   505→    } catch {
   506→      return 0;
   507→    }
   508→  }
   509→
   510→  /**
   511→   * Guess language from file extension.
   512→   */
   513→  private guessLanguage(fsPath: string): string {
   514→    const ext = fsPath.split('.').pop()?.toLowerCase() || '';
   515→    const map: Record<string, string> = {
   516→      ts: 'typescript', tsx: 'typescriptreact', js: 'javascript', jsx: 'javascriptreact',
   517→      py: 'python', go: 'go', rs: 'rust', java: 'java', rb: 'ruby',
   518→      md: 'markdown', json: 'json', yml: 'yaml', yaml: 'yaml',
   519→      css: 'css', html: 'html', sh: 'shellscript', sql: 'sql',
   520→    };
   521→    return map[ext] || ext;
   522→  }
   523→
   524→  /**
   525→   * Set the active model and persist it.
   526→   */
   527→  async setModel(modelId: string): Promise<void> {
   528→    this.activeModel = getModel(modelId);
   529→    this.estimator.setProvider(this.activeModel.provider);
   530→    if (this.workspaceState) {
   531→      this.workspaceState.update(SELECTED_MODEL_KEY, modelId);
   532→    }
   533→    // Sync the VS Code setting so Settings UI / dashboard selector stay in sync
   534→    const cfg = vscode.workspace.getConfiguration('tokalator');
   535→    const currentSetting = cfg.get<string>('model');
   536→    if (currentSetting !== modelId) {
   537→      await cfg.update('model', modelId, vscode.ConfigurationTarget.Global);
   538→    }
   539→    // Rescan workspace with new tokenizer ratios, then refresh dashboard
   540→    await this.scanWorkspaceFiles();
   541→    await this.refresh();
   542→  }
   543→
   544→  /**
   545→   * Get the current active model.
   546→   */
   547→  getActiveModel(): ModelProfile {
   548→    return this.activeModel;
   549→  }
   550→
   551→  /**
   552→   * Get all available models.
   553→   */
   554→  getModels(): ModelProfile[] {
   555→    return MODEL_PROFILES;
   556→  }
   557→
   558→  /**
   559→   * Get the tokenizer service for direct token counting.
   560→   */
   561→  getTokenizer(): TokenizerService {
   562→    return this.tokenizer;
   563→  }
   564→
   565→  /**
   566→   * Scan workspace files to estimate total project token count.
   567→   * This runs once on startup and on workspace change.
   568→   */
   569→  private async scanWorkspaceFiles(): Promise<void> {
   570→    try {
   571→      const files = await vscode.workspace.findFiles(
   572→        '**/*.{ts,tsx,js,jsx,py,go,rs,java,rb,md,json,yml,yaml,css,html,sh,sql,c,cpp,h,cs,swift,kt}',
   573→        '{**/node_modules/**,**/dist/**,**/build/**,**/.next/**,**/vendor/**,**/.git/**}',
   574→        5000
   575→      );
   576→      this.workspaceFileCount = files.length;
   577→
   578→      // Estimate total workspace tokens using provider-specific byte ratios
   579→      let totalBytes = 0;
   580→      for (const uri of files) {
   581→        try {
   582→          const stat = await vscode.workspace.fs.stat(uri);
   583→          totalBytes += stat.size;
   584→        } catch {
   585→          // skip unreadable files
   586→        }
   587→      }
   588→      this.workspaceFileTokens = this.tokenizer.estimateFromBytes(totalBytes, this.activeModel.provider);
   589→    } catch {
   590→      this.workspaceFileCount = 0;
   591→      this.workspaceFileTokens = 0;
   592→    }
   593→  }
   594→
   595→  /**
   596→   * Save a session summary to workspace state for next activation.
   597→   */
   598→  saveSessionSummary(): void {
   599→    const snapshot = this.latestSnapshot;
   600→    if (!snapshot || !this.workspaceState) return;
   601→
   602→    const topFiles = [...this.fileEditCounts.entries()]
   603→      .sort((a, b) => b[1] - a[1])
   604→      .slice(0, 5)
   605→      .map(([uri]) => {
   606→        try {
   607→          return vscode.workspace.asRelativePath(vscode.Uri.parse(uri));
   608→        } catch {
   609→          return uri;
   610→        }
   611→      });
   612→
   613→    const summary: SessionSummary = {
   614→      endedAt: new Date().toISOString(),
   615→      modelId: this.activeModel.id,
   616→      modelLabel: this.activeModel.label,
   617→      totalTurns: this.chatTurnCount,
   618→      peakTokens: this.peakTokens,
   619→      peakPercent: this.peakPercent,
   620→      tabCount: snapshot.tabs.length,
   621→      pinnedCount: this.pinnedFiles.size,
   622→      filesWorkedOn: topFiles,
   623→      budgetLevel: snapshot.budgetLevel,
   624→      healthStatus: snapshot.contextHealth,
   625→    };
   626→
   627→    this.workspaceState.update(SESSION_KEY, summary);
   628→  }
   629→
   630→  /**
   631→   * Get last session summary (if any).
   632→   */
   633→  getLastSession(): SessionSummary | undefined {
   634→    return this.workspaceState?.get<SessionSummary>(SESSION_KEY);
   635→  }
   636→
   637→  dispose(): void {
   638→    this.saveSessionSummary();
   639→    if (this.refreshTimer) { clearInterval(this.refreshTimer); }
   640→    if (this.debounceTimer) { clearTimeout(this.debounceTimer); }
   641→    this._onDidUpdateSnapshot.dispose();
   642→    this.tokenizer.dispose();
   643→    this.disposables.forEach(d => d.dispose());
   644→  }
   645→}
