    16→ *  /instructions — List and estimate tokens for instruction files
    17→ *  /model        — Show or switch the active AI model
    18→ *  /compaction   — Per-turn token growth and compaction recommendations
    19→ *  /reset        — Reset session state (turn counter)
    20→ */
    21→export class ContextChatParticipant implements vscode.Disposable {
    22→
    23→  private participant: vscode.ChatParticipant;
    24→
    25→  constructor(private readonly monitor: ContextMonitor) {
    26→    this.participant = vscode.chat.createChatParticipant(
    27→      'tokalator.tokens',
    28→      this.handleRequest.bind(this),
    29→    );
    30→
    31→    this.participant.iconPath = new vscode.ThemeIcon('symbol-numeric');
    32→  }
    33→
    34→  private async handleRequest(
    35→    request: vscode.ChatRequest,
    36→    context: vscode.ChatContext,
    37→    stream: vscode.ChatResponseStream,
    38→    token: vscode.CancellationToken,
    39→  ): Promise<vscode.ChatResult> {
    40→
    41→    // Only count turns for commands that modify state (optimize, pin, unpin)
    42→    // Read-only commands (count, breakdown) don't contribute to context rot
    43→    const isModifyingCommand = request.command === 'optimize' || request.command === 'pin' || request.command === 'unpin';
    44→    if (isModifyingCommand) {
    45→      this.monitor.incrementChatTurns();
    46→    }
    47→
    48→    switch (request.command) {
    49→      case 'count':
    50→        return this.handleCount(stream);
    51→
    52→      case 'optimize':
    53→        return this.handleOptimize(stream);
    54→
    55→      case 'pin':
    56→        return this.handlePin(request, stream);
    57→
    58→      case 'unpin':
    59→        return this.handleUnpin(request, stream);
    60→
    61→      case 'breakdown':
    62→        return this.handleBreakdown(stream);
    63→
    64→      case 'instructions':
    65→        return this.handleInstructions(stream);
    66→
    67→      case 'model':
    68→        return this.handleModel(request, stream);
    69→
    70→      case 'reset':
    71→        return this.handleReset(stream);
    72→
    73→      case 'compaction':
    74→        return this.handleCompaction(stream);
    75→
    76→      case 'preview':
    77→        return this.handlePreview(request, stream);
    78→
    79→      case 'exit':
    80→        return this.handleExit(stream);
    81→
    82→      default:
