    84→    }
    85→  }
    86→
    87→  /**
    88→   * /count — Token count and budget level
    89→   */
    90→  private async handleCount(stream: vscode.ChatResponseStream): Promise<vscode.ChatResult> {
    91→    await this.monitor.refresh();
    92→    const snapshot = this.monitor.getLatestSnapshot();
    93→
    94→    if (!snapshot) {
    95→      stream.markdown('Unable to get token count.');
    96→      return {};
    97→    }
    98→
    99→    const levelEmoji = snapshot.budgetLevel === 'low' ? '🟢'
   100→      : snapshot.budgetLevel === 'medium' ? '🟡' : '🔴';
   101→
   102→    stream.markdown(`## ${levelEmoji} Token Budget: ${snapshot.budgetLevel.toUpperCase()}\n\n`);
   103→
   104→    // Simple summary
   105→    stream.markdown(`| | |\n|---|---|\n`);
   106→    stream.markdown(`| **Tabs open** | ${snapshot.tabs.length} |\n`);
   107→    stream.markdown(`| **Tokens used** | ~${this.fmtTokens(snapshot.totalEstimatedTokens)} |\n`);
   108→    stream.markdown(`| **Window size** | ${this.fmtTokens(snapshot.windowCapacity)} |\n`);
   109→    stream.markdown(`| **Tokenizer** | ${snapshot.tokenizerLabel} |\n`);
   110→    stream.markdown(`| **Chat turns** | ${snapshot.chatTurnCount} |\n\n`);
   111→
   112→    // Health notes
   113→    for (const reason of snapshot.healthReasons) {
   114→      stream.markdown(`- ${reason}\n`);
   115→    }
   116→
   117→    // Quick actions
   118→    const config = vscode.workspace.getConfiguration('tokalator');
   119→    const threshold = config.get<number>('relevanceThreshold', 0.3);
   120→    const distractors = snapshot.tabs.filter(t => t.relevanceScore < threshold && !t.isActive && !t.isPinned);
   121→
   122→    if (distractors.length > 0) {
   123→      stream.markdown(`\n> **${distractors.length} low-relevance tabs** — run \`@tokalator /optimize\` to close them\n`);
   124→    }
   125→
   126→    return {};
   127→  }
   128→
   129→  /**
   130→   * /optimize — Close low-relevance tabs
