   310→  /**
   311→   * /compaction — Per-turn token growth and compaction recommendations
   312→   */
   313→  private async handleCompaction(stream: vscode.ChatResponseStream): Promise<vscode.ChatResult> {
   314→    await this.monitor.refresh();
   315→    const snapshot = this.monitor.getLatestSnapshot();
   316→
   317→    if (!snapshot) {
   318→      stream.markdown('Unable to get compaction data.');
   319→      return {};
   320→    }
   321→
   322→    const model = this.monitor.getActiveModel();
   323→    const history = snapshot.turnHistory;
   324→    const breakdown = snapshot.budgetBreakdown;
   325→
   326→    stream.markdown(`## Context Growth\n\n`);
   327→
   328→    // Current budget breakdown
   329→    stream.markdown(`### Budget Breakdown\n\n`);
   330→    stream.markdown(`| Category | Tokens | % of Window |\n|---|---|---|\n`);
   331→    const entries: [string, number][] = [
   332→      ['Files', breakdown.files],
   333→      ['System prompt', breakdown.systemPrompt],
   334→      ['Instructions', breakdown.instructions],
   335→      ['Conversation', breakdown.conversation],
   336→      ['Output reserve', breakdown.outputReservation],
   337→    ];
   338→    for (const [label, tokens] of entries) {
   339→      const pct = ((tokens / snapshot.windowCapacity) * 100).toFixed(1);
   340→      stream.markdown(`| ${label} | ~${this.fmtTokens(tokens)} | ${pct}% |\n`);
   341→    }
   342→    stream.markdown(`| **Total** | **~${this.fmtTokens(snapshot.totalEstimatedTokens)}** | **${snapshot.usagePercent.toFixed(1)}%** |\n\n`);
   343→
   344→    // Per-turn history table
   345→    if (history.length > 0) {
   346→      stream.markdown(`### Turn History\n\n`);
   347→      stream.markdown(`| Turn | Input | Files | Overhead | Tabs | Pinned |\n|---|---|---|---|---|---|\n`);
   348→
   349→      for (const t of history) {
   350→        stream.markdown(`| ${t.turn} | ~${this.fmtTokens(t.inputTokens)} | ~${this.fmtTokens(t.fileTokens)} | ~${this.fmtTokens(t.overheadTokens)} | ${t.tabCount} | ${t.pinnedCount} |\n`);
   351→      }
   352→
   353→      // Growth analysis
   354→      stream.markdown(`\n### Growth Analysis\n\n`);
   355→
   356→      const avgGrowth = history.length >= 2
   357→        ? (history[history.length - 1].inputTokens - history[0].inputTokens) / (history.length - 1)
   358→        : 0;
   359→
   360→      const firstFile = history[0].fileTokens;
   361→      const lastFile = history[history.length - 1].fileTokens;
   362→      const fileTrend = lastFile > firstFile * 1.1 ? 'growing' : lastFile < firstFile * 0.9 ? 'shrinking' : 'stable';
   363→
   364→      stream.markdown(`- **Conversation cost:** ~800 tokens/turn (estimated)\n`);
   365→      if (history.length >= 2) {
   366→        stream.markdown(`- **Input growth rate:** ~${this.fmtTokens(Math.round(avgGrowth))}/turn\n`);
   367→      }
   368→      stream.markdown(`- **File tokens:** ${fileTrend} (${this.fmtTokens(firstFile)} → ${this.fmtTokens(lastFile)})\n`);
   369→      stream.markdown(`- **Output reserved:** ~${this.fmtTokens(model.maxOutput)} per response\n\n`);
   370→    } else {
   371→      stream.markdown(`*No turn history yet.* Use \`@tokalator /pin\`, \`/optimize\`, or \`/unpin\` to start tracking.\n\n`);
   372→    }
   373→
   374→    // Actionable suggestions
   375→    const suggestions: string[] = [];
   376→
   377→    const config = vscode.workspace.getConfiguration('tokalator');
   378→    const threshold = config.get<number>('relevanceThreshold', 0.3);
   379→    const distractors = snapshot.tabs.filter(t => t.relevanceScore < threshold && !t.isActive && !t.isPinned);
   380→    if (distractors.length > 0) {
   381→      const saveable = distractors.reduce((s, t) => s + t.estimatedTokens, 0);
   382→      suggestions.push(`Close ${distractors.length} low-relevance tabs to save ~${this.fmtTokens(saveable)} tokens`);
   383→    }
   384→
   385→    const turnsLeft = model.rotThreshold - snapshot.chatTurnCount;
   386→    if (turnsLeft <= 5 && turnsLeft > 0) {
   387→      suggestions.push(`${turnsLeft} turns until context rot threshold (${model.rotThreshold}) — consider \`/reset\``);
   388→    } else if (turnsLeft <= 0) {
   389→      suggestions.push(`Past context rot threshold (${model.rotThreshold} turns) — run \`/reset\` to clear`);
   390→    }
   391→
   392→    const inputPct = snapshot.usagePercent;
   393→    if (inputPct >= 80) {
   394→      suggestions.push(`Input is ${inputPct.toFixed(0)}% of window — compaction point reached`);
   395→    } else if (inputPct >= 60) {
   396→      suggestions.push(`Input is ${inputPct.toFixed(0)}% of window — approaching compaction point`);
   397→    }
   398→
   399→    const pinnedCount = snapshot.pinnedFiles.size;
   400→    if (pinnedCount > 5) {
   401→      suggestions.push(`${pinnedCount} files pinned — unpin files you're done with`);
   402→    }
   403→
   404→    if (suggestions.length > 0) {
   405→      stream.markdown(`### Recommendations\n\n`);
   406→      for (const s of suggestions) {
   407→        stream.markdown(`- ${s}\n`);
   408→      }
   409→    } else {
   410→      stream.markdown(`> Context looks healthy — no compaction needed yet.\n`);
   411→    }
   412→
   413→    return {};
   414→  }
