   502→  private async handleInstructions(stream: vscode.ChatResponseStream): Promise<vscode.ChatResult> {
   503→    stream.progress('Scanning instruction files...');
   504→
   505→    // Find all instruction-like files
   506→    const patterns = [
   507→      '**/*.instructions.md',
   508→      '**/.github/copilot-instructions.md',
   509→      '**/.copilot/*.md',
   510→      '**/*.prompt.md',
   511→      '**/.cursorrules',
   512→      '**/.claude/**/*.md',
   513→      '**/AGENTS.md',
   514→      '**/*.agent.md',
   515→    ];
   516→
   517→    const allFiles: { path: string; tokens: number }[] = [];
   518→
   519→    for (const pattern of patterns) {
   520→      try {
   521→        const files = await vscode.workspace.findFiles(pattern, '**/node_modules/**', 50);
   522→        for (const uri of files) {
   523→          try {
   524→            const doc = await vscode.workspace.openTextDocument(uri);
   525→            const model = this.monitor.getActiveModel();
   526→            const tokenizer = this.monitor.getTokenizer();
   527→            const tokens = tokenizer.countTokens(doc.getText(), model.provider);
   528→            allFiles.push({
   529→              path: vscode.workspace.asRelativePath(uri),
   530→              tokens,
   531→            });
   532→          } catch {
   533→            allFiles.push({ path: vscode.workspace.asRelativePath(uri), tokens: 0 });
   534→          }
   535→        }
   536→      } catch {
   537→        // pattern not found
   538→      }
   539→    }
   540→
   541→    if (allFiles.length === 0) {
   542→      stream.markdown('No instruction files found in this workspace.\n\n');
   543→      stream.markdown('Instruction files are automatically attached to AI context. Common patterns:\n\n');
   544→      stream.markdown('| File | Used by |\n|---|---|\n');
   545→      stream.markdown('| `.github/copilot-instructions.md` | GitHub Copilot |\n');
   546→      stream.markdown('| `*.instructions.md` | GitHub Copilot |\n');
