   548→      stream.markdown('| `AGENTS.md` | Claude Code |\n');
   549→      stream.markdown('| `.cursorrules` | Cursor |\n');
   550→      return {};
   551→    }
   552→
   553→    // Sort by tokens descending
   554→    allFiles.sort((a, b) => b.tokens - a.tokens);
