   559→    stream.markdown(`| File | Tokens |\n|---|---|\n`);
   560→
   561→    for (const f of allFiles) {
   562→      stream.markdown(`| \`${f.path}\` | ~${this.fmtTokens(f.tokens)} |\n`);
   563→    }
   564→
   565→    const model = this.monitor.getActiveModel();
   566→    const pct = ((totalTokens / model.contextWindow) * 100).toFixed(1);
   567→    stream.markdown(`\n> Instructions use **${pct}%** of ${model.label}'s ${this.fmtTokens(model.contextWindow)} context window\n`);
   568→
   569→    return {};
   570→  }
