   713→        </ul>
   714→
   715→        \${chatTurnCount > 0 ? '<button class="action-btn secondary" data-action="resetTurns">Reset Turn Counter</button>' : ''}
   716→      \`;
   717→    }
   718→
   719→    function renderTab(t) {
   720→      var safeUri = encodeURIComponent(t.uri);
   721→      var pinBtn = t.isPinned
   722→        ? '<button title="Unpin" data-action="unpin" data-uri="' + safeUri + '">\u{1F4CC}</button>'
