     1→/**
     2→ * Model-specific tokenizer service.
     3→ *
     4→ * Uses real BPE tokenizers per provider family:
     5→ *  - Anthropic (Claude): Claude-specific BPE ranks via @anthropic-ai/tokenizer data
     6→ *  - OpenAI (GPT/o-series): o200k_base encoding (GPT-4o, GPT-5.x, o3, o4-mini)
     7→ *  - Google (Gemini): heuristic (~1 token per 4 chars) — no official JS tokenizer
     8→ *
     9→ * Both real tokenizers use js-tiktoken's pure-JS BPE engine (no WASM).
    10→ */
    11→
    12→import { Tiktoken } from 'js-tiktoken/lite';
    13→
    14→export type TokenizerType = 'claude-bpe' | 'o200k_base' | 'heuristic';
    15→
    16→export class TokenizerService {
    17→
    18→  private claudeTokenizer: Tiktoken | null = null;
    19→  private openaiTokenizer: Tiktoken | null = null;
    20→
    21→  /**
    22→   * Get the tokenizer type used for a given provider.
    23→   */
    24→  getTokenizerType(provider: string): TokenizerType {
    25→    switch (provider) {
    26→      case 'anthropic': return 'claude-bpe';
    27→      case 'openai': return 'o200k_base';
    28→      default: return 'heuristic';
    29→    }
    30→  }
    31→
    32→  /**
    33→   * Human-readable label for the tokenizer in use.
    34→   */
    35→  getTokenizerLabel(provider: string): string {
    36→    switch (provider) {
    37→      case 'anthropic': return 'Claude BPE tokenizer';
    38→      case 'openai': return 'o200k_base tokenizer';
    39→      default: return 'Heuristic (~4 chars/token)';
    40→    }
    41→  }
    42→
    43→  /**
    44→   * Count tokens in text using the real tokenizer for the given provider.
    45→   * Falls back to heuristic if the tokenizer fails to load.
    46→   */
    47→  countTokens(text: string, provider: string): number {
    48→    try {
    49→      switch (provider) {
    50→        case 'anthropic': return this.countClaude(text);
    51→        case 'openai': return this.countOpenAI(text);
    52→        default: return this.heuristic(text);
    53→      }
    54→    } catch {
    55→      return this.heuristic(text);
    56→    }
    57→  }
    58→
    59→  /**
    60→   * Estimate tokens from raw byte size (for workspace scanning without reading files).
    61→   * Uses provider-specific bytes-per-token ratios measured on code corpora.
    62→   */
    63→  estimateFromBytes(bytes: number, provider: string): number {
    64→    switch (provider) {
    65→      case 'anthropic': return Math.ceil(bytes / 3.7);
    66→      case 'openai': return Math.ceil(bytes / 3.5);
    67→      default: return Math.ceil(bytes / 4);
    68→    }
    69→  }
    70→
    71→  // --- Anthropic: Claude BPE tokenizer ---
    72→
    73→  private countClaude(text: string): number {
    74→    if (!this.claudeTokenizer) {
    75→      // Lazy-load Claude BPE ranks (696 KB JSON) on first use
    76→      const ranks = require('@anthropic-ai/tokenizer/claude.json');
    77→      this.claudeTokenizer = new Tiktoken(ranks);
    78→    }
    79→    return this.claudeTokenizer.encode(text.normalize('NFKC')).length;
    80→  }
    81→
    82→  // --- OpenAI: o200k_base tokenizer ---
    83→
    84→  private countOpenAI(text: string): number {
    85→    if (!this.openaiTokenizer) {
    86→      // Lazy-load o200k_base ranks on first use
    87→      const ranks = require('js-tiktoken/ranks/o200k_base');
    88→      this.openaiTokenizer = new Tiktoken(ranks);
    89→    }
    90→    return this.openaiTokenizer.encode(text).length;
    91→  }
    92→
    93→  // --- Fallback ---
    94→
    95→  private heuristic(text: string): number {
    96→    return Math.ceil(text.length / 4);
    97→  }
    98→
    99→  /**
   100→   * Release tokenizer memory.
   101→   */
   102→  dispose(): void {
   103→    this.claudeTokenizer = null;
   104→    this.openaiTokenizer = null;
   105→  }
   106→}
