    61→  );
    62→  if (labelExact) return labelExact;
    63→
    64→  // 3. Starts-with on id or label
    65→  const startsWith = MODEL_PROFILES.find(m => {
    66→    const mid = m.id.toLowerCase().replace(/[^a-z0-9.]/g, '');
    67→    const mlabel = m.label.toLowerCase().replace(/[^a-z0-9.]/g, '');
    68→    return mid.startsWith(q) || mlabel.startsWith(q);
    69→  });
    70→  if (startsWith) return startsWith;
    71→
    72→  // 4. Contains match (fallback)
    73→  return MODEL_PROFILES.find(m => {
