   335→
   336→    // 3. Score relevance
   337→    tabs = this.scorer.scoreAll(tabs, vscode.window.activeTextEditor);
   338→
   339→    // 4. Sort by relevance (highest first)
   340→    tabs.sort((a, b) => b.relevanceScore - a.relevanceScore);
   341→
   342→    // 5. Gather diagnostics summary
   343→    const diagnosticsSummary = this.gatherDiagnosticsSummary();
   344→
   345→    // 6. Count instruction files in workspace
   346→    const instructionFiles = await this.countInstructionFiles();
   347→
   348→    // 7. Compute budget
   349→    const budget = this.estimator.computeBudget(
   350→      tabs,
   351→      this.chatTurnCount,
   352→      instructionFiles,
   353→      windowCapacity
   354→    );
   355→
   356→    // Track peak usage for session summary
   357→    if (budget.used > this.peakTokens) {
   358→      this.peakTokens = budget.used;
   359→      this.peakPercent = budget.percent;
   360→    }
   361→
   362→    // 8. Determine budget level (simplified from percentage)
   363→    let budgetLevel: 'low' | 'medium' | 'high';
   364→    if (budget.percent > 85) {
   365→      budgetLevel = 'high';
   366→    } else if (budget.percent > 60) {
   367→      budgetLevel = 'medium';
   368→    } else {
   369→      budgetLevel = 'low';
   370→    }
   371→
   372→    // 9. Determine health and reasons
   373→    const healthReasons: string[] = [];
   374→    let contextHealth: ContextSnapshot['contextHealth'] = 'healthy';
   375→
   376→    if (budgetLevel === 'high') {
   377→      contextHealth = 'critical';
   378→      healthReasons.push('Token budget is high — context overflow risk');
   379→    } else if (budgetLevel === 'medium') {
   380→      contextHealth = 'warning';
   381→      healthReasons.push('Token budget is medium — consider closing unused tabs');
   382→    }
   383→
   384→    if (this.chatTurnCount >= rotWarning) {
   385→      contextHealth = contextHealth === 'critical' ? 'critical' : 'warning';
   386→      healthReasons.push(`${this.chatTurnCount} chat turns — context may be stale`);
   387→    }
   388→
   389→    const distractors = tabs.filter(t => {
   390→      const threshold = config.get<number>('relevanceThreshold', 0.3);
   391→      return t.relevanceScore < threshold && !t.isActive && !t.isPinned;
   392→    });
   393→    if (distractors.length > 3) {
   394→      contextHealth = contextHealth === 'critical' ? 'critical' : 'warning';
   395→      healthReasons.push(`${distractors.length} low-relevance tabs open`);
   396→    }
   397→
   398→    if (healthReasons.length === 0) {
   399→      healthReasons.push('Token budget looks good');
   400→    }
   401→
   402→    const activeFile = tabs.find(t => t.isActive) || null;
   403→
   404→    return {
   405→      timestamp: Date.now(),
   406→      activeFile,
   407→      tabs,
   408→      pinnedFiles: this.pinnedFiles,
   409→      totalEstimatedTokens: budget.used,
   410→      windowCapacity,
   411→      usagePercent: budget.percent,
   412→      budgetLevel,
   413→      diagnosticsSummary,
