   619→      totalTurns: this.chatTurnCount,
   620→      peakTokens: this.peakTokens,
   621→      peakPercent: this.peakPercent,
   622→      tabCount: snapshot.tabs.length,
   623→      pinnedCount: this.pinnedFiles.size,
   624→      filesWorkedOn: topFiles,
   625→      budgetLevel: snapshot.budgetLevel,
