                command: "npx",
                args: ["-y", "@modelcontextprotocol/server-github"],
                env: {
                  GITHUB_TOKEN: process.env.GITHUB_TOKEN
                }
              }
            },
            allowedTools: ["mcp__github__list_issues", "mcp__github__search_issues"]
          }
        };
    ```

