        mcp_servers={
            "github": {
                "command": "npx",
                "args": ["-y", "@modelcontextprotocol/server-github"],
                "env": {"GITHUB_TOKEN": os.environ["GITHUB_TOKEN"]},
            }
        },
        allowed_tools=["mcp__github__list_issues", "mcp__github__search_issues"],
    )
    ```

    </CodeGroup>
  </Tab>
  <Tab title=".mcp.json">
