\hline
Web platform library (\texttt{lib/}) & 3,243 & 10 \\
\hline
Library tests & 899 & 4 \\
\hline
React components & 4,811 & 22 \\
\hline
App pages (\texttt{app/}) & 3,675 & 28 \\
\hline
Content (JSON) & 1,795 & 5 \\
\hline
\textbf{Total TypeScript/TSX} & \textbf{20,814} & -- \\
\hline
\end{tabular}
